/**
 * Typed client for the Edge Function BFF, generated by hand from the
 * @steadyflow/core contracts (packages/core/src/contracts). Every call
 * validates its response against the procedure's output schema, so a
 * contract drift between an Edge Function and its Zod schema fails loudly
 * here instead of silently reaching the UI as `undefined` fields.
 *
 * Server-only: needs the caller's Supabase access token, which server
 * components/route handlers already hold from the session.
 */

import type {
  AnalyzeShopInput,
  AuditQueryInput,
  IntentCancelInput,
  IntentListInput,
  KeysSetInput,
  KeysTestInput,
  ListInsightsInput,
  OrgLlmConfigInput,
  ReportGenerateInput,
} from '@steadyflow/core';
import {
  AnalyzeShopOutput,
  AuditQueryOutput,
  IntentCancelOutput,
  IntentListOutput,
  KeysListOutput,
  KeysSetOutput,
  KeysTestOutput,
  ListInsightsOutput,
  error as makeError,
  OrgLlmConfigOutput,
  ReportGenerateOutput,
  SteadyFlowError,
} from '@steadyflow/core';
import { z } from 'zod';

export type ApiResult<T> = { ok: true; data: T } | { ok: false; error: SteadyFlowError };

const ErrorEnvelope = z.object({ error: SteadyFlowError });

const functionsBaseUrl = (): string => {
  const base = process.env.NEXT_PUBLIC_SUPABASE_URL;
  if (!base) throw new Error('Missing required env var: NEXT_PUBLIC_SUPABASE_URL');
  return `${base}/functions/v1`;
};

const queryString = (params: Record<string, string | number | undefined>): string => {
  const search = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value !== undefined) search.set(key, String(value));
  }
  const s = search.toString();
  return s ? `?${s}` : '';
};

async function callFunction<O>(
  accessToken: string,
  slug: string,
  outputSchema: z.ZodType<O>,
  init: {
    method: 'GET' | 'POST';
    query?: Record<string, string | number | undefined>;
    body?: unknown;
  },
): Promise<ApiResult<O>> {
  const url = `${functionsBaseUrl()}/${slug}${init.query ? queryString(init.query) : ''}`;

  let res: Response;
  try {
    res = await fetch(url, {
      method: init.method,
      headers: {
        Authorization: `Bearer ${accessToken}`,
        ...(init.body !== undefined ? { 'content-type': 'application/json' } : {}),
      },
      ...(init.body !== undefined ? { body: JSON.stringify(init.body) } : {}),
      cache: 'no-store',
    });
  } catch (err) {
    return {
      ok: false,
      error: makeError('TIMEOUT', err instanceof Error ? err.message : 'Network request failed'),
    };
  }

  let payload: unknown;
  try {
    payload = await res.json();
  } catch {
    return { ok: false, error: makeError('INTERNAL', `Non-JSON response (HTTP ${res.status})`) };
  }

  if (!res.ok) {
    const parsedErr = ErrorEnvelope.safeParse(payload);
    return {
      ok: false,
      error: parsedErr.success ? parsedErr.data.error : makeError('INTERNAL', `HTTP ${res.status}`),
    };
  }

  const parsed = outputSchema.safeParse(payload);
  if (!parsed.success) {
    return {
      ok: false,
      error: makeError('VALIDATION_FAILED', `${slug} response failed contract validation`, {
        issues: parsed.error.issues,
      }),
    };
  }
  return { ok: true, data: parsed.data };
}

export const createApiClient = (accessToken: string) => ({
  insightsList: (input: Partial<z.infer<typeof ListInsightsInput>> = {}) =>
    callFunction(accessToken, 'insights-list', ListInsightsOutput, {
      method: 'GET',
      query: { category: input.category, limit: input.limit, cursor: input.cursor },
    }),

  auditQuery: (input: Partial<z.infer<typeof AuditQueryInput>> = {}) =>
    callFunction(accessToken, 'audit-query', AuditQueryOutput, {
      method: 'GET',
      query: {
        limit: input.limit,
        cursor: input.cursor,
        action: input.action,
        outcome: input.outcome,
      },
    }),

  keysList: () => callFunction(accessToken, 'keys-list', KeysListOutput, { method: 'GET' }),

  keysSet: (input: z.infer<typeof KeysSetInput>) =>
    callFunction(accessToken, 'keys-set', KeysSetOutput, { method: 'POST', body: input }),

  keysTest: (input: z.infer<typeof KeysTestInput>) =>
    callFunction(accessToken, 'keys-test', KeysTestOutput, { method: 'POST', body: input }),

  intentList: (input: Partial<z.infer<typeof IntentListInput>> = {}) =>
    // Edge function directory is `intel-list` (procedure name is `intent.list`) — naming predates this client.
    callFunction(accessToken, 'intel-list', IntentListOutput, {
      method: 'GET',
      query: { kind: input.kind, status: input.status, limit: input.limit, cursor: input.cursor },
    }),

  intentCancel: (input: z.infer<typeof IntentCancelInput>) =>
    // Edge function directory is `intel-cancel` (procedure name is `intent.cancel`).
    callFunction(accessToken, 'intel-cancel', IntentCancelOutput, { method: 'POST', body: input }),

  analyzeShop: (input: z.infer<typeof AnalyzeShopInput>) =>
    callFunction(accessToken, 'intel-analyze-shop', AnalyzeShopOutput, {
      method: 'POST',
      body: input,
    }),

  orgLlmConfigGet: () =>
    callFunction(accessToken, 'org-llm-config-get', OrgLlmConfigOutput, { method: 'GET' }),

  orgLlmConfigSet: (input: z.infer<typeof OrgLlmConfigInput>) =>
    callFunction(accessToken, 'org-llm-config-set', OrgLlmConfigOutput, {
      method: 'POST',
      body: input,
    }),

  reportGenerate: (input: z.infer<typeof ReportGenerateInput>) =>
    callFunction(accessToken, 'report-generate', ReportGenerateOutput, {
      method: 'POST',
      body: input,
    }),
});

export type ApiClient = ReturnType<typeof createApiClient>;

/**
 * Maps a SteadyFlowError to the interface state a page should show.
 * Distinguishes "the user isn't signed in" from "a configured provider
 * is broken" from "something else went wrong" — the three error-shaped
 * states callers need to render differently.
 */
export type ErrorState = 'auth' | 'provider-auth-failure' | 'rate-limited' | 'not-found' | 'error';

export const classifyError = (error: SteadyFlowError): ErrorState => {
  switch (error.code) {
    case 'UNAUTHENTICATED':
    case 'FORBIDDEN':
      return 'auth';
    case 'KEY_MISSING':
    case 'KEY_INVALID':
    case 'PROVIDER_ERROR':
    case 'PROVIDER_UNAVAILABLE':
    case 'ENVELOPE_DECRYPT_FAILED':
      return 'provider-auth-failure';
    case 'RATE_LIMITED':
      return 'rate-limited';
    case 'NOT_FOUND':
      return 'not-found';
    default:
      return 'error';
  }
};
